  1	// Package webhook delivers payment events to merchant endpoints with signed
  2	// payloads, retries with exponential backoff and a dead-letter list.
  3	package webhook
  4	
  5	import (
  6		"context"
  7		"encoding/json"
  8		"fmt"
  9		"net/http"
 10		"sync"
 11		"time"
 12	
 13		"example.com/gopayments/clock"
 14		"example.com/gopayments/payment"
 15	)
 16	
 17	// Event is the webhook payload.
 18	type Event struct {
 19		ID         string          `json:"id"`
 20		Type       string          `json:"type"`
 21		MerchantID string          `json:"merchant_id"`
 22		CreatedAt  time.Time       `json:"created_at"`
 23		Data       json.RawMessage `json:"data"`
 24	}
 25	
 26	// Endpoint is a merchant's webhook destination.
 27	type Endpoint struct {
 28		URL    string
 29		Secret string
 30	}
 31	
 32	// Endpoints resolves the endpoint of a merchant.
 33	type Endpoints interface {
 34		Endpoint(merchantID string) (Endpoint, bool)
 35	}
 36	
 37	// StaticEndpoints is a fixed merchant -> endpoint map.
 38	type StaticEndpoints map[string]Endpoint
 39	
 40	// Endpoint implements Endpoints.
 41	func (s StaticEndpoints) Endpoint(merchantID string) (Endpoint, bool) {
 42		e, ok := s[merchantID]
 43		return e, ok
 44	}
 45	
 46	// Policy controls retries.
 47	type Policy struct {
 48		MaxAttempts int
 49		BaseDelay   time.Duration
 50		MaxDelay    time.Duration
 51	}
 52	
 53	// DefaultPolicy is the production retry policy.
 54	func DefaultPolicy() Policy {
 55		return Policy{MaxAttempts: 6, BaseDelay: time.Second, MaxDelay: 10 * time.Minute}
 56	}
 57	
 58	// Backoff is the wait after failed attempt n (n >= 1): BaseDelay * 2^(n-1),
 59	// capped at MaxDelay.
 60	func (p Policy) Backoff(n int) time.Duration {
 61		d := p.BaseDelay
 62		for i := 1; i < n; i++ {
 63			if d >= p.MaxDelay/2 {
 64				return p.MaxDelay
 65			}
 66			d *= 2
 67		}
 68		return min(d, p.MaxDelay)
 69	}
 70	
 71	// DeadLetter is an event that exhausted its retries or failed permanently.
 72	type DeadLetter struct {
 73		Event      Event
 74		Attempts   int
 75		LastStatus int
 76		LastError  string
 77		FailedAt   time.Time
 78	}
 79	
 80	// Dispatcher queues events and delivers them.
 81	type Dispatcher struct {
 82		sender    Sender
 83		endpoints Endpoints
 84		clock     clock.Clock
 85		policy    Policy
 86	
 87		mu        sync.Mutex
 88		seq       int
 89		queue     []Event
 90		dead      []DeadLetter
 91		delivered int
 92	}
 93	
 94	var _ payment.Publisher = (*Dispatcher)(nil)
 95	
 96	// NewDispatcher wires a dispatcher.
 97	func NewDispatcher(sender Sender, endpoints Endpoints, clk clock.Clock, policy Policy) *Dispatcher {
 98		return &Dispatcher{sender: sender, endpoints: endpoints, clock: clk, policy: policy}
 99	}
100	
101	type paymentData struct {
102		PaymentID string `json:"payment_id"`
103		Status    string `json:"status"`
104		Amount    string `json:"amount"`
105		Currency  string `json:"currency"`
106		Refunded  string `json:"refunded_amount"`
107		RefundID  string `json:"refund_id,omitempty"`
108	}
109	
110	// Publish implements payment.Publisher by queueing a webhook event.
111	func (d *Dispatcher) Publish(_ context.Context, ev payment.Event) error {
112		data := paymentData{
113			PaymentID: ev.Payment.ID,
114			Status:    string(ev.Payment.Status),
115			Amount:    ev.Payment.Amount.Decimal(),
116			Currency:  ev.Payment.Amount.Currency.Code,
117			Refunded:  ev.Payment.RefundedAmount().Decimal(),
118		}
119		if ev.Refund != nil {
120			data.RefundID = ev.Refund.ID
121		}
122		raw, err := json.Marshal(data)
123		if err != nil {
124			return fmt.Errorf("encode %s event: %w", ev.Type, err)
125		}
126		d.mu.Lock()
127		defer d.mu.Unlock()
128		d.seq++
129		d.queue = append(d.queue, Event{
130			ID:         fmt.Sprintf("evt_%06d", d.seq),
131			Type:       ev.Type,
132			MerchantID: ev.Payment.MerchantID,
133			CreatedAt:  d.clock.Now(),
134			Data:       raw,
135		})
136		return nil
137	}
138	
139	// Pending returns the number of queued, undelivered events.
140	func (d *Dispatcher) Pending() int {
141		d.mu.Lock()
142		defer d.mu.Unlock()
143		return len(d.queue)
144	}
145	
146	// Delivered returns how many events were delivered successfully.
147	func (d *Dispatcher) Delivered() int {
148		d.mu.Lock()
149		defer d.mu.Unlock()
150		return d.delivered
151	}
152	
153	// DeadLetters returns a snapshot of the dead-letter list.
154	func (d *Dispatcher) DeadLetters() []DeadLetter {
155		d.mu.Lock()
156		defer d.mu.Unlock()
157		return append([]DeadLetter(nil), d.dead...)
158	}
159	
160	// Flush delivers every queued event. It returns early only if ctx is done;
161	// undelivered events stay queued in that case.
162	func (d *Dispatcher) Flush(ctx context.Context) error {
163		d.mu.Lock()
164		batch := d.queue
165		d.queue = nil
166		d.mu.Unlock()
167	
168		for i, ev := range batch {
169			if err := d.deliver(ctx, ev); err != nil {
170				d.mu.Lock()
171				d.queue = append(append([]Event(nil), batch[i:]...), d.queue...)
172				d.mu.Unlock()
173				return fmt.Errorf("flush webhooks: %w", err)
174			}
175		}
176		return nil
177	}
178	
179	// deliver attempts ev until success, a permanent failure or MaxAttempts.
180	// It only returns an error when ctx is done.
181	func (d *Dispatcher) deliver(ctx context.Context, ev Event) error {
182		ep, ok := d.endpoints.Endpoint(ev.MerchantID)
183		if !ok {
184			return nil // merchant has no webhook configured
185		}
186		body, err := json.Marshal(ev)
187		if err != nil {
188			d.deadLetter(ev, 0, 0, fmt.Errorf("encode event: %w", err))
189			return nil
190		}
191		var (
192			status  int
193			sendErr error
194			attempt int
195		)
196		for attempt = 1; attempt <= d.policy.MaxAttempts; attempt++ {
197			headers := map[string]string{
198				"Content-Type":  "application/json",
199				"Webhook-Id":    ev.ID,
200				SignatureHeader: Sign(ep.Secret, d.clock.Now().Unix(), body),
201			}
202			status, sendErr = d.sender.Send(ctx, Delivery{EventID: ev.ID, URL: ep.URL, Body: body, Headers: headers, Attempt: attempt})
203			if sendErr == nil && status >= 200 && status < 300 {
204				d.mu.Lock()
205				d.delivered++
206				d.mu.Unlock()
207				return nil
208			}
209			if !retryable(status, sendErr) || attempt == d.policy.MaxAttempts {
210				break
211			}
212			if err := d.clock.Sleep(ctx, d.policy.Backoff(attempt)); err != nil {
213				return err
214			}
215		}
216		d.deadLetter(ev, attempt, status, sendErr)
217		return nil
218	}
219	
220	func (d *Dispatcher) deadLetter(ev Event, attempts, status int, err error) {
221		dl := DeadLetter{Event: ev, Attempts: attempts, LastStatus: status, FailedAt: d.clock.Now()}
222		if err != nil {
223			dl.LastError = err.Error()
224		}
225		d.mu.Lock()
226		defer d.mu.Unlock()
227		d.dead = append(d.dead, dl)
228	}
