11	// Delivery is one HTTP attempt of an event to a merchant endpoint.
12	type Delivery struct {
13		EventID string
14		URL     string
15		Body    []byte
16		Headers map[string]string
17		Attempt int
18	}
19	
20	// Sender performs one delivery attempt. A transport error is returned as err;
21	// any HTTP response (including 4xx/5xx) is returned as status with err == nil.
22	type Sender interface {
23		Send(ctx context.Context, d Delivery) (status int, err error)
24	}
25	
26	// HTTPSender delivers over HTTP.
27	type HTTPSender struct {
28		Client *http.Client
29	}
30	
31	// Send implements Sender.
32	func (s HTTPSender) Send(ctx context.Context, d Delivery) (int, error) {
33		req, err := http.NewRequestWithContext(ctx, http.MethodPost, d.URL, bytes.NewReader(d.Body))
34		if err != nil {
35			return 0, fmt.Errorf("build request for %s: %w", d.URL, err)
36		}
37		for k, v := range d.Headers {
38			req.Header.Set(k, v)
39		}
40		client := s.Client
41		if client == nil {
42			client = http.DefaultClient
43		}
44		resp, err := client.Do(req)
45		if err != nil {
46			return 0, fmt.Errorf("post %s: %w", d.URL, err)
47		}
48		defer resp.Body.Close()
49		_, _ = io.Copy(io.Discard, resp.Body)
50		return resp.StatusCode, nil
51	}

