 54	func TestSignVerify(t *testing.T) {
 55		now := time.Unix(1_800_000_000, 0)
 56		body := []byte(`{"id":"evt_1"}`)
 57		h := Sign("k", now.Unix(), body)
 58		tests := []struct {
 59			name    string
 60			secret  string
 61			body    []byte
 62			now     time.Time
 63			wantErr error
 64		}{
 65			{"valid", "k", body, now, nil},
 66			{"wrong secret", "other", body, now, ErrBadSignature},
 67			{"tampered body", "k", []byte(`{"id":"evt_2"}`), now, ErrBadSignature},
 68			{"stale", "k", body, now.Add(10 * time.Minute), ErrStaleSignature},
 69		}
 70		for _, tt := range tests {
 71			t.Run(tt.name, func(t *testing.T) {
 72				err := Verify(tt.secret, h, tt.body, tt.now, 5*time.Minute)
 73				if !errors.Is(err, tt.wantErr) {
 74					t.Fatalf("Verify = %v, want %v", err, tt.wantErr)
 75				}
 76			})
 77		}
 78	}
