 80	func TestBackoffSchedule(t *testing.T) {
 81		p := Policy{MaxAttempts: 10, BaseDelay: time.Second, MaxDelay: 10 * time.Second}
 82		want := []time.Duration{time.Second, 2 * time.Second, 4 * time.Second, 8 * time.Second, 10 * time.Second, 10 * time.Second}
 83		for i, w := range want {
 84			if got := p.Backoff(i + 1); got != w {
 85				t.Errorf("Backoff(%d) = %s, want %s", i+1, got, w)
 86			}
 87		}
 88	}
