 90	func TestDeliverSuccessFirstTry(t *testing.T) {
 91		s := &scriptedSender{}
 92		d, _ := newDispatcher(s)
 93		publishOne(t, d, "m_1")
 94		if err := d.Flush(context.Background()); err != nil {
 95			t.Fatal(err)
 96		}
 97		if len(s.calls) != 1 || d.Delivered() != 1 || d.Pending() != 0 {
 98			t.Fatalf("calls %d delivered %d pending %d", len(s.calls), d.Delivered(), d.Pending())
 99		}
100		c := s.calls[0]
101		if err := Verify("s3cret", c.Headers[SignatureHeader], c.Body, time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC), time.Minute); err != nil {
102			t.Fatalf("signature: %v", err)
103		}
104	}
