106	func TestDeliverRetriesNetworkErrors(t *testing.T) {
107		boom := errors.New("connection reset")
108		s := &scriptedSender{statuses: []int{0, 0}, errs: []error{boom, boom}}
109		d, clk := newDispatcher(s)
110		publishOne(t, d, "m_1")
111		if err := d.Flush(context.Background()); err != nil {
112			t.Fatal(err)
113		}
114		if len(s.calls) != 3 || d.Delivered() != 1 {
115			t.Fatalf("calls %d delivered %d", len(s.calls), d.Delivered())
116		}
117		if got := clk.Sleeps(); len(got) != 2 || got[0] != time.Second || got[1] != 2*time.Second {
118			t.Fatalf("sleeps = %v", got)
119		}
