135		var gotSig string
136		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
137			gotSig = r.Header.Get(SignatureHeader)
138			w.WriteHeader(http.StatusAccepted)
139		}))
