func TestDeliverPermanentStatusNotRetried(t *testing.T) {
	for _, code := range []int{
		http.StatusMovedPermanently,
		http.StatusFound,
		http.StatusBadRequest,
		http.StatusUnauthorized,
		http.StatusForbidden,
		http.StatusNotFound,
		http.StatusGone,
		http.StatusUnprocessableEntity,
	} {
		t.Run(http.StatusText(code), func(t *testing.T) {
			s := &scriptedSender{statuses: []int{code}}
			d, clk := newDispatcher(s)
			publishOne(t, d, "m_1")
			if err := d.Flush(context.Background()); err != nil {
				t.Fatal(err)
			}
			if len(s.calls) != 1 || d.Delivered() != 0 || d.Pending() != 0 {
				t.Fatalf("calls %d delivered %d pending %d", len(s.calls), d.Delivered(), d.Pending())
			}
			if sleeps := clk.Sleeps(); len(sleeps) != 0 {
				t.Fatalf("unexpected sleeps %v", sleeps)
			}
			dead := d.DeadLetters()
			if len(dead) != 1 {
				t.Fatalf("dead letters = %d, want 1", len(dead))
			}
			if dead[0].Attempts != 1 || dead[0].LastStatus != code || dead[0].LastError != "" {
				t.Fatalf("dead letter = %+v, want attempts=1 status=%d", dead[0], code)
			}
		})
	}
}

func TestDeliverRetriesTransientStatusesUntilSuccess(t *testing.T) {
	for _, code := range []int{
		http.StatusRequestTimeout,
		http.StatusTooManyRequests,
		http.StatusInternalServerError,
		http.StatusBadGateway,
		http.StatusServiceUnavailable,
		http.StatusGatewayTimeout,
	} {
		t.Run(http.StatusText(code), func(t *testing.T) {
			s := &scriptedSender{statuses: []int{code, code, http.StatusNoContent}}
			d, clk := newDispatcher(s)
			publishOne(t, d, "m_1")
			if err := d.Flush(context.Background()); err != nil {
				t.Fatal(err)
			}
			if len(s.calls) != 3 || d.Delivered() != 1 || len(d.DeadLetters()) != 0 {
				t.Fatalf("calls %d delivered %d dead %d", len(s.calls), d.Delivered(), len(d.DeadLetters()))
			}
			for i, c := range s.calls {
				if c.Attempt != i+1 {
					t.Fatalf("call %d Attempt = %d, want %d", i, c.Attempt, i+1)
				}
			}
			wantSleeps := []time.Duration{time.Second, 2 * time.Second}
			if got := clk.Sleeps(); len(got) != len(wantSleeps) || got[0] != wantSleeps[0] || got[1] != wantSleeps[1] {
				t.Fatalf("sleeps = %v, want %v", got, wantSleeps)
			}
		})
	}
}

