179	// deliver attempts ev until success, a permanent failure or MaxAttempts.
180	// It only returns an error when ctx is done.
181	func (d *Dispatcher) deliver(ctx context.Context, ev Event) error {
182		ep, ok := d.endpoints.Endpoint(ev.MerchantID)
183		if !ok {
184			return nil // merchant has no webhook configured
185		}
186		body, err := json.Marshal(ev)
187		if err != nil {
188			d.deadLetter(ev, 0, 0, fmt.Errorf("encode event: %w", err))
189			return nil
190		}
191		maxAttempts := max(1, d.policy.MaxAttempts)
192		var (
193			status  int
194			sendErr error
195			attempt int
196		)
197		for attempt = 1; attempt <= maxAttempts; attempt++ {
198			if err := ctx.Err(); err != nil {
199				return err
200			}
201			headers := map[string]string{
202				"Content-Type":  "application/json",
203				"Webhook-Id":    ev.ID,
204				SignatureHeader: Sign(ep.Secret, d.clock.Now().Unix(), body),
205			}
206			status, sendErr = d.sender.Send(ctx, Delivery{EventID: ev.ID, URL: ep.URL, Body: body, Headers: headers, Attempt: attempt})
207			if sendErr == nil && status >= 200 && status < 300 {
208				d.mu.Lock()
209				d.delivered++
210				d.mu.Unlock()
211				return nil
212			}
213			if sendErr != nil && ctx.Err() != nil {
214				return ctx.Err()
215			}
216			if !retryable(status, sendErr) || attempt == maxAttempts {
217				break
218			}
219			if err := d.clock.Sleep(ctx, d.policy.Backoff(attempt)); err != nil {
220				return err
221			}
222		}
223		d.deadLetter(ev, attempt, status, sendErr)
224		return nil
225	}
