227	func (d *Dispatcher) deadLetter(ev Event, attempts, status int, err error) {
228		dl := DeadLetter{Event: ev, Attempts: attempts, LastStatus: status, FailedAt: d.clock.Now()}
229		if err != nil {
230			dl.LastError = err.Error()
231		}
232		d.mu.Lock()
233		defer d.mu.Unlock()
234		d.dead = append(d.dead, dl)
235	}
