237	// retryable reports whether a failed attempt should be retried: transport
238	// errors, 408, 429 and 5xx are transient; any other status is permanent.
239	func retryable(status int, err error) bool {
240		if err != nil {
241			return true
242		}
243		return status == http.StatusRequestTimeout || status == http.StatusTooManyRequests || (status >= 500 && status < 600)
244	}
